create or replace function cashflow.weekly_action_outcome(p_tenant_id uuid)returns jsonb language sql stable security invoker set search_path=cashflow,public as $$with ranked as(select id,week_start,snapshot,row_number()over(order by week_start desc)rn,count(*)over()close_count from cashflow.weekly_financial_close where tenant_id=p_tenant_id and owner_id=auth.uid()),target as(select*from ranked where rn=case when close_count>=2 then 2 else 1 end),latest as(select*from ranked where rn=1),actions as(select count(*)total,count(*)filter(where status='DONE')done,count(*)filter(where status<>'DONE'and due_date<current_date)overdue,count(expected_cash_impact)declared_impact_count,sum(expected_cash_impact)filter(where expected_cash_impact is not null)expected_impact,sum(expected_cash_impact)filter(where status='DONE'and expected_cash_impact is not null)completed_expected_impact from cashflow.msp_task where weekly_close_id=(select id from target)and owner_id=auth.uid()and source='WEEKLY_CLOSE')select jsonb_build_object('plan_week_start',(select week_start from target),'has_close_comparison',coalesce((select close_count>=2 from target),false),'total_actions',coalesce(actions.total,0),'completed_actions',coalesce(actions.done,0),'overdue_actions',coalesce(actions.overdue,0),'declared_impact_count',coalesce(actions.declared_impact_count,0),'expected_cash_impact',actions.expected_impact,'completed_expected_cash_impact',actions.completed_expected_impact,'actual_cash_change',case when(select close_count>=2 from target)then coalesce((select(snapshot#>>'{core,current_cash}')::numeric from latest),0)-coalesce((select(snapshot#>>'{core,current_cash}')::numeric from target),0)else null end)from actions$$;
revoke all on function cashflow.weekly_action_outcome(uuid)from public,anon;grant execute on function cashflow.weekly_action_outcome(uuid)to authenticated;
